package org.sleepwell.app;

import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class HeadphoneCueTest {
    static final HeadphoneCue.Endpoint WIRED=new HeadphoneCue.Endpoint(10,HeadphoneCue.Kind.WIRED),USB=new HeadphoneCue.Endpoint(11,HeadphoneCue.Kind.USB_HEADSET),BLE=new HeadphoneCue.Endpoint(12,HeadphoneCue.Kind.BLE_HEADSET),SPEAKER=new HeadphoneCue.Endpoint(1,HeadphoneCue.Kind.OTHER),A2DP=new HeadphoneCue.Endpoint(2,HeadphoneCue.Kind.BLUETOOTH_MEDIA);
    static final class Clock implements HeadphoneCue.Scheduler {long now;long order;static final class Task{long at,order;Runnable run;Task(long at,long order,Runnable run){this.at=at;this.order=order;this.run=run;}}PriorityQueue<Task> tasks=new PriorityQueue<>(Comparator.<Task>comparingLong(t->t.at).thenComparingLong(t->t.order));public void later(Runnable task,long delay){tasks.add(new Task(now+delay,order++,task));}public long now(){return now;}void advance(long millis){long target=now+millis;int count=0;while(!tasks.isEmpty()&&tasks.peek().at<=target){assertTrue("Bounded scheduler",++count<1000);Task task=tasks.remove();now=task.at;task.run.run();}now=target;}}
    static class Sink implements HeadphoneCue.Sink {List<HeadphoneCue.Endpoint> available=List.of(WIRED),routes=List.of();HeadphoneCue.Endpoint chosen;Runnable changed;int frames,starts,closes,mutes,chunks,partial=320;boolean preference=true,race,drain=true;public List<HeadphoneCue.Endpoint> available(){return available;}public boolean prefer(HeadphoneCue.Endpoint value){chosen=value;return preference;}public void startSilent(Runnable value){starts++;changed=value;}public List<HeadphoneCue.Endpoint> routed(){return routes;}public int chunk(HeadphoneCue.Endpoint expected,int intensity,int frame,int count){chunks++;if(race)routes=List.of(SPEAKER);if(!HeadphoneCue.matches(routes,expected))return -1;int written=Math.min(partial,count);frames+=written;return written;}public boolean drained(){return drain;}public void silence(){mutes++;}public void close(){closes++;}void route(HeadphoneCue.Endpoint... devices){routes=Arrays.asList(devices);if(changed!=null)changed.run();}}
    private SnoreCuePolicy.Settings settings(int repeats){return new SnoreCuePolicy.Settings(true,SnoreCuePolicy.Mode.SOUND,1,repeats,1,true);}
    @Test public void connectedOrPreferredDeviceDoesNotAuthorizeAnUnverifiedSpeakerRoute(){Clock clock=new Clock();Sink sink=new Sink();sink.routes=List.of(SPEAKER);List<String> errors=new ArrayList<>();HeadphoneCue cue=new HeadphoneCue(sink,clock,()->true,errors::add);cue.start(settings(1));assertEquals(WIRED,sink.chosen);assertEquals(1,sink.starts);clock.advance(1520);assertEquals(0,sink.frames);assertEquals(1,sink.closes);assertTrue(errors.get(0).contains("not be verified"));}
    @Test public void actualSingleSelectedRouteAllowsBoundedSoundAfterSilentSetup(){Clock clock=new Clock();Sink sink=new Sink();HeadphoneCue cue=new HeadphoneCue(sink,clock,()->true,message->{});cue.start(settings(1));clock.advance(300);assertEquals(0,sink.frames);sink.route(WIRED);clock.advance(400);assertEquals(4000,sink.frames);assertEquals(1,sink.closes);assertEquals(1,sink.mutes);}
    @Test public void routeLossImmediatelyMutesFlushesAndFencesQueuedChunks(){Clock clock=new Clock();Sink sink=new Sink();HeadphoneCue cue=new HeadphoneCue(sink,clock,()->true,message->{});cue.start(settings(3));sink.route(WIRED);clock.advance(80);assertTrue(sink.frames>0);int before=sink.frames;sink.route(SPEAKER);assertEquals(1,sink.mutes);assertEquals(1,sink.closes);clock.advance(5000);sink.route(WIRED);clock.advance(100);assertEquals(before,sink.frames);}
    @Test public void secondRouteCheckRejectsLossBetweenCoordinatorCheckAndWrite(){Clock clock=new Clock();Sink sink=new Sink();sink.race=true;HeadphoneCue cue=new HeadphoneCue(sink,clock,()->true,message->{});cue.start(settings(1));sink.route(WIRED);clock.advance(50);assertEquals(1,sink.chunks);assertEquals(0,sink.frames);assertEquals(1,sink.closes);}
    @Test public void unsupportedBluetoothAndGenericDevicesNeverStartAnAudioTrack(){Clock clock=new Clock();Sink sink=new Sink();sink.available=List.of(A2DP,SPEAKER);HeadphoneCue cue=new HeadphoneCue(sink,clock,()->true,message->{});cue.start(settings(1));assertEquals(0,sink.starts);assertEquals(0,sink.frames);assertEquals(1,sink.closes);assertEquals(WIRED,HeadphoneCue.select(List.of(BLE,USB,WIRED)));assertEquals(USB,HeadphoneCue.select(List.of(BLE,USB)));assertEquals(BLE,HeadphoneCue.select(List.of(A2DP,BLE)));}
    @Test public void duplicateRoutesAndWrongHeadphonesAreRejected(){assertFalse(HeadphoneCue.matches(null,WIRED));assertFalse(HeadphoneCue.matches(List.of(),WIRED));assertFalse(HeadphoneCue.matches(List.of(WIRED,SPEAKER),WIRED));assertFalse(HeadphoneCue.matches(List.of(USB),WIRED));assertFalse(HeadphoneCue.matches(List.of(new HeadphoneCue.Endpoint(10,HeadphoneCue.Kind.OTHER)),WIRED));assertTrue(HeadphoneCue.matches(List.of(WIRED),WIRED));}
    @Test public void revokedLifecycleTokenClosesAndLateCallbacksCannotRestart(){Clock clock=new Clock();Sink sink=new Sink();boolean[] live={true};HeadphoneCue cue=new HeadphoneCue(sink,clock,()->live[0],message->{});cue.start(settings(2));sink.route(WIRED);clock.advance(40);int before=sink.frames;live[0]=false;clock.advance(20);assertEquals(1,sink.closes);cue.close();sink.route(WIRED);cue.start(settings(1));clock.advance(3000);assertEquals(1,sink.closes);assertEquals(before,sink.frames);}
    @Test public void partialAndInitiallyFullNonblockingBuffersDoNotDropOrInventFrames(){Clock clock=new Clock();Sink sink=new Sink();sink.partial=0;HeadphoneCue cue=new HeadphoneCue(sink,clock,()->true,message->{});cue.start(settings(1));sink.route(WIRED);clock.advance(100);assertEquals(0,sink.frames);sink.partial=160;sink.drain=false;clock.advance(700);assertEquals(4000,sink.frames);assertEquals(0,sink.closes);sink.drain=true;clock.advance(20);assertEquals(1,sink.closes);}
    @Test public void repeatedCallbacksAreCoalescedAndRepeatBudgetStaysExact(){Clock clock=new Clock();Sink sink=new Sink();HeadphoneCue cue=new HeadphoneCue(sink,clock,()->true,message->{});cue.start(settings(3));for(int n=0;n<40;n++)sink.route(WIRED);assertEquals(1,clock.tasks.size());clock.advance(3000);assertEquals(12000,sink.frames);assertEquals(1,sink.closes);}
    @Test public void unavailablePreferenceAndStuckBufferFailClosedWithBoundedWork(){Clock clock=new Clock();Sink sink=new Sink();sink.preference=false;HeadphoneCue cue=new HeadphoneCue(sink,clock,()->true,message->{});cue.start(settings(1));assertEquals(0,sink.starts);assertEquals(1,sink.closes);Clock other=new Clock();Sink stuck=new Sink();stuck.partial=0;HeadphoneCue stalled=new HeadphoneCue(stuck,other,()->true,message->{});stalled.start(settings(1));stuck.route(WIRED);other.advance(3600);assertEquals(1,stuck.closes);assertEquals(0,stuck.frames);assertTrue(stuck.chunks<180);SnoreCuePolicy.Settings preview=SnoreCuePolicy.previewSettings(SnoreCuePolicy.Mode.BOTH,2,true);assertTrue(preview.headphoneSound);assertEquals(1,preview.intensity);assertEquals(1,preview.repeats);}
    @Test public void routeCallbackFailureStillClosesEveryOwnedResource(){Clock clock=new Clock();boolean[] broken={false};Sink sink=new Sink(){public List<HeadphoneCue.Endpoint> routed(){if(broken[0])throw new IllegalStateException();return super.routed();}public void silence(){super.silence();throw new IllegalStateException();}};List<String> errors=new ArrayList<>();HeadphoneCue cue=new HeadphoneCue(sink,clock,()->true,errors::add);cue.start(settings(1));sink.route(WIRED);clock.advance(40);broken[0]=true;sink.changed.run();clock.advance(100);assertEquals(1,sink.closes);assertEquals(1,sink.mutes);assertTrue(errors.stream().anyMatch(text->text.contains("route is unavailable")));assertTrue(errors.stream().anyMatch(text->text.contains("stopped cleanly")));}
}
